#include <stdio.h>

/* Lesson 1 of 6 — Hello.
   Press RUN. Change the message, then RUN again. */

int main(void) {
    printf("hello from lilC\n");
    return 0;
}

#include <stdio.h>

/* Lesson 2 of 6 — Variables.
   Change year and press RUN. */

int main(void) {
    int year = 2026;
    printf("year = %d\n", year);
    return 0;
}

#include <stdio.h>

/* Lesson 3 of 6 — If.
   Change temp and press RUN. Try 15. */

int main(void) {
    int temp = 28;
    if (temp >= 20) {
        printf("warm\n");
    } else {
        printf("cool\n");
    }
    return 0;
}

#include <stdio.h>

/* Lesson 4 of 6 — Loop.
   Change the 5 to 3 and press RUN. */

int main(void) {
    int n;
    for (n = 1; n <= 5; n = n + 1) {
        printf("%d\n", n);
    }
    return 0;
}

#include <stdio.h>

/* Lesson 5 of 6 — Array.
   Change a value in nums and press RUN. */

int main(void) {
    int nums[4];
    int i;
    int sum;
    nums[0] = 2;
    nums[1] = 4;
    nums[2] = 6;
    nums[3] = 8;
    sum = 0;
    for (i = 0; i < 4; i = i + 1) {
        sum = sum + nums[i];
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>

/* Lesson 6 of 6 — Function.
   Change 21 and press RUN. */

int twice(int n) {
    return n * 2;
}

int main(void) {
    printf("%d\n", twice(21));
    return 0;
}
